import {
  Component,
  Input,
  Output,
  EventEmitter,
  ViewChild,
  ElementRef,
  AfterViewInit,
  OnDestroy,
  ViewEncapsulation,
  Inject,
  PLATFORM_ID,
  NgZone,
  Renderer2,
  OnChanges,
  SimpleChanges,
} from '@angular/core';

import { CommonModule, isPlatformBrowser } from '@angular/common';
import type { PagiflowInstance, PagiflowOptions } from './types';

// @ts-ignore
import PagiflowCore from 'pagiflow';

type PagiflowCtor = (
  selector: string | HTMLElement,
  opts?: PagiflowOptions
) => PagiflowInstance;

function getPagiflow(): PagiflowCtor | null {
  if (typeof window !== 'undefined' && (window as any).Pagiflow) {
    return (window as any).Pagiflow as PagiflowCtor;
  }
  return (PagiflowCore as any).default ?? PagiflowCore;
}

function initPagiflowFromElement(
  ctor: PagiflowCtor,
  el: HTMLElement,
  opts: PagiflowOptions,
  renderer: Renderer2
): PagiflowInstance | null {
  const attrValue = `pf-${Math.random().toString(36).slice(2)}`;
  const selector = `[data-pagiflow-angular-id="${attrValue}"]`;
  renderer.setAttribute(el, 'data-pagiflow-angular-id', attrValue);

  const bySelector = ctor(selector, opts) as PagiflowInstance | null;
  if (!bySelector) {
    renderer.removeAttribute(el, 'data-pagiflow-angular-id');
    return null;
  }
  return bySelector;
}

// ─── Pagiflow Component ───────────────────────────────────────────────────────
@Component({
  selector: 'pf-pagiflow',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div
      #track
      [ngClass]="['pagiflow', className || '']"
      [style]="style"
    >
      <ng-content></ng-content>
    </div>
  `,
  encapsulation: ViewEncapsulation.None,
})
export class PagiflowComponent implements AfterViewInit, OnDestroy, OnChanges {
  @ViewChild('track', { read: ElementRef }) trackRef!: ElementRef<HTMLDivElement>;

  // Input options
  @Input() options: PagiflowOptions = {};
  @Input() className?: string;
  @Input() style?: Record<string, string | number>;

  // Output events
  @Output() slideChange = new EventEmitter<number>();
  @Output() ready = new EventEmitter<PagiflowInstance>();

  private instance: PagiflowInstance | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private raf1 = 0;
  private raf2 = 0;
  private timeoutId = 0;
  private destroyed = false;

  constructor(
    @Inject(PLATFORM_ID) private platformId: Object,
    private ngZone: NgZone,
    private renderer: Renderer2,
    private hostRef: ElementRef<HTMLElement>
  ) {}

  ngAfterViewInit(): void {
    this.destroyed = false;
    if (!isPlatformBrowser(this.platformId)) return;
    // Wait one frame so projected slide content is fully rendered before core snapshots children.
    this.ngZone.runOutsideAngular(() => {
      requestAnimationFrame(() => {
        if (!this.destroyed) this.initPagiflow();
      });
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!changes['options'] || !this.instance || changes['options'].firstChange) return;

    // Reconfigure existing instance when Angular input object changes.
    this.scheduleReinit();
  }

  ngOnDestroy(): void {
    this.destroyed = true;
    this.destroy();
  }

  private initPagiflow(): void {
    if (!isPlatformBrowser(this.platformId)) return;

    const el = this.trackRef.nativeElement;
    const existing = (el as any).pagiflowInstance as PagiflowInstance | undefined;

    let inst: PagiflowInstance | null = null;

    if (existing && !existing.destroyed) {
      inst = existing;
    } else {
      const ctor = getPagiflow();
      if (!ctor) {
        console.error('[PagiflowComponent] Pagiflow core not found. Install pagiflow or load it via CDN.');
        return;
      }
      inst = initPagiflowFromElement(ctor, el, this.options, this.renderer);
    }

    if (!inst) return;

    this.instance = inst;
    (el as any).pagiflowInstance = inst;
    (this.hostRef.nativeElement as any).pagiflowInstance = inst;
    this.ready.emit(inst);

    // Listen to slide changes via the instance API
    inst.onSlideChange((idx) => {
      this.ngZone.run(() => {
        this.slideChange.emit(idx);
      });
    });

    const syncLayout = () => {
      const api = this.instance as (PagiflowInstance & { update?: () => void }) | null;
      api?.update?.();
    };

    // Setup resize observer for responsive behavior
    this.ngZone.runOutsideAngular(() => {
      this.resizeObserver = new ResizeObserver(() => {
        syncLayout();
      });
      this.resizeObserver.observe(el);
    });

    // Keep behavior aligned with other wrappers so sync/thumbnails settle after mount.
    this.raf1 = requestAnimationFrame(() => syncLayout());
    this.raf2 = requestAnimationFrame(() => syncLayout());
    this.timeoutId = window.setTimeout(() => syncLayout(), 80);
    window.addEventListener('load', syncLayout, { once: true });

    // Keep a final layout sync after mount without resetting slide index.
    this.raf1 = requestAnimationFrame(() => syncLayout());
  }

  private scheduleReinit(): void {
    if (!isPlatformBrowser(this.platformId)) return;
    cancelAnimationFrame(this.raf1);
    this.raf1 = requestAnimationFrame(() => {
      cancelAnimationFrame(this.raf2);
      this.raf2 = requestAnimationFrame(() => {
        const host = this.trackRef?.nativeElement;
        if (this.destroyed || !this.instance || !host || !host.isConnected) return;
        try {
          this.instance.reInit(this.options);
        } catch {
          // Ignore transient rebuild errors during rapid teardown/remount.
        }
      });
    });
  }

  private destroy(): void {
    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }
    if (isPlatformBrowser(this.platformId)) {
      cancelAnimationFrame(this.raf1);
      cancelAnimationFrame(this.raf2);
      clearTimeout(this.timeoutId);
    }

    if (this.instance && !this.instance.destroyed) {
      this.instance.destroy();
    }
    delete (this.hostRef.nativeElement as any).pagiflowInstance;
    this.instance = null;
  }

  // Public API methods

  /**
   * Get the underlying Pagiflow instance.
   */
  getInstance(): PagiflowInstance | null {
    return this.instance;
  }

  /**
   * Navigate to the next slide.
   */
  next(): void {
    this.instance?.next();
  }

  /**
   * Navigate to the previous slide.
   */
  prev(): void {
    this.instance?.prev();
  }

  /**
   * Go to a specific slide index.
   */
  goTo(index: number, opts?: { silent?: boolean; instant?: boolean }): void {
    this.instance?.goTo(index, opts);
  }

  /**
   * Start autoScroll.
   */
  play(): void {
    this.instance?.play();
  }

  /**
   * Pause autoScroll.
   */
  pause(): void {
    this.instance?.pause();
  }

  /**
   * Resume autoScroll after pause.
   */
  resume(): void {
    this.instance?.resume();
  }

  /**
   * Toggle autoScroll play/pause state.
   */
  togglePlayPause(): void {
    this.instance?.togglePlayPause();
  }

  /**
   * Update options and optionally rebuild.
   */
  setOptions(opts: Partial<PagiflowOptions>, rebuild?: boolean): void {
    this.instance?.setOptions(opts, rebuild);
  }

  /**
   * Reinitialize with new or updated options.
   */
  reInit(opts?: Partial<PagiflowOptions>): void {
    this.instance?.reInit(opts);
  }
}

// ─── Pagiflow Slide Component ─────────────────────────────────────────────────
/**
 * Component or directive to wrap individual slides.
 * Use \`<pf-slide>\` to create a wrapper element, or use \`[pf-slide]\` as an attribute
 * on your own element to avoid an extra DOM wrapper.
 */
@Component({
  selector: 'pf-slide, [pf-slide]',
  standalone: true,
  template: `<ng-content></ng-content>`,
  host: {
    '[class]': "className ? 'pf-slide ' + className : 'pf-slide'",
    '[style]': 'style'
  },
  encapsulation: ViewEncapsulation.None,
})
export class PagiflowSlideComponent {
  @Input() className?: string;
  @Input() style?: string | Record<string, string | number>;
}
